package com.squareup.workflow1.internal.compose

import androidx.compose.runtime.Composer

/**
 * Keys for manual [Composer] calls in the compose runtime. Such keys would normally be generated by
 * the compose compiler. The only requirement for these keys is that they are unique within their
 * parent group, so hard-coding them to trivial values is fine.
 */
internal object ComposeGroupKeys {
  const val RENDER_WORKFLOW_RESTART_GROUP = 1
  const val RENDER_WORKFLOW_SKIP_GROUP = 2
  const val RENDER_CONTEXT_CHILD_GROUP = 3
}
